from collections import deque, defaultdict

def numBusesToDestination(routes, S, T):
    if S == T:
        return 0

    # Create a graph where each node is a bus stop and edges represent direct connections between stops
    stop_to_buses = defaultdict(set)
    for bus, route in enumerate(routes):
        for stop in route:
            stop_to_buses[stop].add(bus)

    # If either S or T is not in any route, return -1
    if S not in stop_to_buses or T not in stop_to_buses:
        return -1

    # BFS to find the shortest path in terms of number of buses
    queue = deque([(S, 0)])  # (current_stop, current_bus_count)
    visited_stops = set([S])
    visited_buses = set()

    while queue:
        current_stop, bus_count = queue.popleft()

        # Check all buses that pass through the current stop
        for bus in stop_to_buses[current_stop]:
            if bus not in visited_buses:
                visited_buses.add(bus)

                # Check all stops on the current bus
                for next_stop in routes[bus]:
                    if next_stop == T:
                        return bus_count + 1
                    if next_stop not in visited_stops:
                        visited_stops.add(next_stop)
                        queue.append((next_stop, bus_count + 1))

    return -1
